@include forFeature('a11yImproveButtonsInCardComponent') {
  cx-card {
    .cx-card-actions:not(:disabled):not(.disabled):active {
      background-color: unset;
    }
    .cx-card-actions {
      border: unset;
      margin-top: 0;
    }
    .cx-card-actions > *:only-child {
      flex: 1;
    }
  }
}

@include forFeature('a11yImproveButtonsInCardComponent') {
  .cx-card-actions {
    gap: 16px;
    cx-generic-link {
      font-weight: var(--cx-font-weight-semi);
      color: var(--cx-color-primary);
      text-decoration: underline;
    }
    .cx-card-action-item {
      display: flex;
      align-items: center;
    }

    button.btn-tertiary {
      color: var(--cx-color-primary);
      border-radius: var(--cx-buttons-border-radius);
      padding: 12px 16px;
      border-style: none;
      &:focus {
        @include visible-focus();
      }
    }
  }
}

onKeyUp(event: KeyboardEvent) {
  if (
    !this.featureConfigService?.isEnabled('a11yNgSelectCloseDropdownOnEscape')
  ) {
    return;
  }
  const jawsEscapeCode = 'AltLeft';
  if (event.code === jawsEscapeCode) {
    this.selectComponent.close();
  }
}

protected getCardRole(isCardSelected: boolean): 'button' | 'application' {
  const isButtonRole =
    this.featureConfigService?.isEnabled(
      'a11ySelectLabelWithContextForSelectedAddrOrPayment'
    ) && !isCardSelected;
  return isButtonRole ? 'button' : 'application';
}

